const fromTemplate = useMutation({
  mutationFn: (name: string) => postJson<Claim>(`${base}/people/${person.id}/template-claims`, { template: name, user }),
  onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
